import sys

def main():
    s = sys.stdin.readline().rstrip('\r\n')
    a = list(s)
    v = set('aeiou')
    for i in range(len(a) - 1):
        if a[i] in v and a[i + 1].islower() and a[i + 1] not in v:
            a[i], a[i + 1] = a[i + 1], a[i]
    print(''.join(c for c in a if 'a' <= c <= 'z'))

